use std::collections::VecDeque;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

pub struct RateLimiter {
    requests: Mutex<VecDeque<Instant>>,
}

impl RateLimiter {
    /// Creates a new `RateLimiter` with a limit of 100 requests per 60 seconds.
    pub fn new() -> Self {
        Self {
            requests: Mutex::new(VecDeque::new()),
        }
    }

    /// Checks if a request is allowed. Thread-safe sliding window implementation.
    pub fn allow_request(&self) -> bool {
        let now = Instant::now();
        let cutoff = now.checked_sub(Duration::from_secs(60)).unwrap_or(now);

        let mut queue = self.requests.lock().unwrap();

        // Explicitly remove all timestamps older than 60 seconds
        while queue.front().map_or(false, |&t| t < cutoff) {
            queue.pop_front();
        }

        // Check the count of remaining elements against the limit
        if queue.len() < 100 {
            queue.push_back(now);
            true
        } else {
            false
        }
    }
}
