#include <iostream>
#include <vector>
#include <unordered_map>

int countSubarrays(const std::vector<int>& arr, int k) {
    std::unordered_map<int, int> prefix_counts;
    prefix_counts[0] = 1;
    int curr_xor = 0;
    int count = 0;

    for (int num : arr) {
        curr_xor ^= num;
        int target = curr_xor ^ k;
        if (prefix_counts.find(target) != prefix_counts.end()) {
            count += prefix_counts[target];
        }
        prefix_counts[curr_xor]++;
    }
    return count;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int n, k;
    if (std::cin >> n >> k) {
        std::vector<int> arr(n);
        for (int i = 0; i < n; ++i) {
            std::cin >> arr[i];
        }
        std::cout << countSubarrays(arr, k) << "\n";
    }
    return 0;
}
