An elegant and optimal $O(N \log(\max A_i))$ solution in C++ to solve this problem.

### Method Explanation
For a fixed right endpoint, as we extend the subarray to the left, the bitwise OR sum can only increase and will change at most $\approx 30$ times (the number of bits in $10^9$). We maintain the set of active OR values ending at the current position, along with the frequency (count) of each value. For each new element, we transition the states, merge duplicate values, and accumulate their contributions to the total sum.

### C++ Code

```cpp
#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    // Optimize standard I/O operations for performance
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    long long total_sum = 0;
    // Stores pairs of {OR_value, count_of_subarrays}
    vector<pair<int, int>> current_ors; 

    for (int x : a) {
        vector<pair<int, int>> next_ors;
        for (const auto& p : current_ors) {
            next_ors.push_back({p.first | x, p.second});
        }
        next_ors.push_back({x, 1});

        // Sort to easily merge duplicates
        sort(next_ors.begin(), next_ors.end());

        vector<pair<int, int>> merged;
        for (const auto& p : next_ors) {
            if (merged.empty() || merged.back().first != p.first) {
                merged.push_back(p);
            } else {
                merged.back().second += p.second;
            }
        }

        current_ors = move(merged);

        // Add the contribution of all subarrays ending at the current index
        for (const auto& p : current_ors) {
            total_sum += (long long)p.first * p.second;
        }
    }

    cout << total_sum << "\n";

    return 0;
}
