export function memoizeAsync<T extends (...args: any[]) => Promise<any>>(
  fn: T,
  cacheKeyResolver: (...args: Parameters<T>) => string
): T {
  const cache = new Map<string, Promise<any>>();

  return function (this: any, ...args: Parameters<T>): Promise<any> {
    const key = cacheKeyResolver(...args);

    if (cache.has(key)) {
      return cache.get(key)!;
    }

    const promise = fn.apply(this, args).catch((error) => {
      cache.delete(key);
      throw error;
    });

    cache.set(key, promise);
    return promise;
  } as unknown as T;
}
```

