use std::sync::Arc;
use std::sync::atomic::{AtomicU64, AtomicUsize, Ordering};
use std::thread;
use std::time::Duration;

pub struct RateLimiter {
    tokens: AtomicU64,
}

impl RateLimiter {
    pub fn new() -> Arc<Self> {
        let limiter = Arc::new(Self {
            tokens: AtomicU64::new(42),
        });

        let limiter_clone = Arc::clone(&limiter);
        thread::spawn(move || {
            loop {
                thread::sleep(Duration::from_millis(100));
                let mut current = limiter_clone.tokens.load(Ordering::Acquire);
                loop {
                    if current >= 42 {
                        break;
                    }
                    let next = std::cmp::min(42, current + 3);
                    match limiter_clone.tokens.compare_exchange_weak(
                        current,
                        next,
                        Ordering::Release,
                        Ordering::Acquire,
                    ) {
                        Ok(_) => break,
                        Err(actual) => current = actual,
                    }
                }
            }
        });

        limiter
    }

    pub fn try_acquire(&self) -> bool {
        let mut current = self.tokens.load(Ordering::Acquire);
        loop {
            if current == 0 {
                return false;
            }
            match self.tokens.compare_exchange_weak(
                current,
                current - 1,
                Ordering::Release,
                Ordering::Acquire,
            ) {
                Ok(_) => return true,
                Err(actual) => current = actual,
            }
        }
    }
}

fn main() {
    let limiter = RateLimiter::new();
    let total_acquired = Arc::new(AtomicUsize::new(0));
    let mut handles = vec![];

    for _ in 0..5 {
        let limiter = Arc::clone(&limiter);
        let total_acquired = Arc::clone(&total_acquired);

        let handle = thread::spawn(move || {
            let mut local_acquired = 0;
            for _ in 0..10 {
                if limiter.try_acquire() {
                    local_acquired += 1;
                }
                thread::sleep(Duration::from_millis(20));
            }
            total_acquired.fetch_add(local_acquired, Ordering::SeqCst);
        });
        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }

    println!(
        "Total tokens successfully acquired: {}",
        total_acquired.load(Ordering::SeqCst)
    );
}
