Union-Find is highly efficient for Kruskal's algorithm because it detects cycles and merges components in near-constant time, $O(\alpha(N))$ per operation. This enables rapid verification of whether adding an edge connects two disjoint components. 

Rank optimization (union-by-rank) ensures that the smaller tree is always attached under the root of the larger tree. This limits the maximum tree height to $O(\log N)$ even without path compression. When combined with path compression, it flattens the structure further, yielding an extremely slow-growing inverse Ackermann complexity, $\alpha(N)$, which is practically $O(1)$ in real-world scenarios.

```python
class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [0] * size

    def find(self, i):
        if self.parent[i] != i:
            self.parent[i] = self.find(self.parent[i])  # Path compression
        return self.parent[i]

    def union(self, i, j):
        root_i = self.find(i)
        root_j = self.find(j)
        if root_i != root_j:
            # Union by rank
            if self.rank[root_i] < self.rank[root_j]:
                self.parent[root_i] = root_j
            elif self.rank[root_i] > self.rank[root_j]:
                self.parent[root_j] = root_i
            else:
                self.parent[root_j] = root_i
                self.rank[root_i] += 1
            return True
        return False

def min_cost_to_connect(n, edges):
    if n <= 1:
        return 0

    uf = UnionFind(n)
    # Sort edges by weight
    sorted_edges = sorted(edges, key=lambda x: x[2])

    mst_weight = 0
    edges_used = 0

    for u, v, weight in sorted_edges:
        if uf.union(u, v):
            mst_weight += weight
            edges_used += 1
            if edges_used == n - 1:
                return mst_weight

    return -1
