impl<T> RateLimiter<T> {
    pub fn new(resource: T, limit: usize, window: Duration) -> Self {
        Self {
            state: Arc::new(Mutex::new(LimiterState {
                resource,
                limit,
                window,
                window_start: Instant::now(),
                count: 0,
            })),
        }
    }

    pub fn execute<F, R>(&self, f: F) -> Option<R>
    where
        F: FnOnce(&T) -> R,
    {
        let mut state = self.state.lock().unwrap();
        let now = Instant::now();

        if now.duration_since(state.window_start) >= state.window {
            state.window_start = now;
            state.count = 0;
        }

        if state.count < state.limit {
            state.count += 1;
            Some(f(&state.resource))
        } else {
            None
        }
    }
}

impl<T> Clone for RateLimiter<T> {
    fn clone(&self) -> Self {
        Self {
            state: Arc::clone(&self.state),
        }
    }
