export function memoizeByReference<T extends object, R>(fn: (arg: T) => R): (arg: T) => R {
  const cache = new WeakMap<T, R>();

  return (arg: T): R => {
    if (cache.has(arg)) {
      return cache.get(arg) as R;
    }
    const result = fn(arg);
    cache.set(arg, result);
    return result;
  };
}
```

### Explanation of the `undefined` Edge Case

To handle `undefined` values correctly, the implementation relies on `WeakMap.prototype.has(arg)` rather than simply checking if `cache.get(arg)` returns a truthy value. 

* **The Problem with `get` alone**: If `fn(arg)` evaluates to `undefined`, calling `cache.get(arg)` would return `undefined`. Without a existence check, a simple falsy check like `if (cache.get(arg) !== undefined)` would mistake a cached `undefined` value for a cache miss, triggering an unnecessary re-computation.
* **The Solution**: `WeakMap.prototype.has(key)` checks for the *presence of the key* in the map, regardless of the value associated with it. When `fn(arg)` returns `undefined`, the pair `(arg, undefined)` is stored in the cache. On subsequent calls, `cache.has(arg)` evaluates to `true`, and the cached `undefined` value is returned directly without re-running `fn`.

